window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1111e2a853407805"]={"versions": [{"id": "FIG-1111e2a853407805", "releases": ["R2.1.20", "R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Profildiagramm (Metamodell-Ausschnitt) im Kontext des AUTOSAR Template Modeling Guide (M2-Ebene). Das Diagramm spezifiziert die Definition des Stereotyps <code>«atpPackage»</code> sowie dessen Bindung an die UML-Infrastruktur-Metaklasse <code>Kernel::Package</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst zwei Modellelemente und eine Extension-Beziehung:</p>\n<ul class=\"fig-list\"><li><code>atpPackage</code>: Stereotyp-Definition zur Kennzeichnung von AUTOSAR-Paketen.\n</li><li><code>Kernel::Package</code>: Ziel-Metaklasse mit den stereotypischen Kennzeichnungen <code>«metaclass»</code> sowie den Rollen- bzw. Generalisierungskontexten <code>Namespace</code> und <code>PackagableElement</code>.\n</li><li><code>«extends»</code>-Beziehung: Gerichtete Stereotyp-Erweiterung von <code>atpPackage</code> nach <code>Kernel::Package</code>, annotiert mit der Eigenschaft <code>{required}</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es ist kein dynamischer Laufzeit- oder Sequenzablauf modelliert. Die Semantik definiert die zwingende (<code>{required}</code>) Erweiterung und Typisierung regulärer UML-Packages zu AUTOSAR-Packages auf Definitionsebene.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für AUTOSAR-Metamodellierungswerkzeuge und Profildefinitionen:</p>\n<ul class=\"fig-list\"><li>Jedes als AUTOSAR-Paket fungierende Modellelement basiert auf der Metaklasse <code>Kernel::Package</code>.\n</li><li>Durch die Profilbeschränkung <code>{required}</code> muss das Stereotyp <code>atpPackage</code> zwingend auf die Metaklasse angewendet werden, um standardkonforme AUTOSAR-Paketstrukturen im Metamodell abzubilden.\n</li><li>Werkzeug- und Codegeneratoren müssen Paketelemente (<code>PackagableElement</code>) innerhalb dieses Namensraums (<code>Namespace</code>) gemäß den Vorgaben des Template Modeling Guide verarbeiten.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-0544b693ef310242", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Profildiagramm (Metamodell-Ausschnitt) im Kontext des AUTOSAR Template Modeling Guide (M2-Ebene). Das Diagramm spezifiziert die Definition des Stereotyps <code>«atpPackage»</code> sowie dessen Bindung an die UML-Infrastruktur-Metaklasse <code>Kernel::Package</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst zwei Modellelemente und eine Extension-Beziehung:</p>\n<ul class=\"fig-list\"><li><code>atpPackage</code>: Stereotyp-Definition zur Kennzeichnung von AUTOSAR-Paketen.\n</li><li><code>Kernel::Package</code>: Ziel-Metaklasse mit den stereotypischen Kennzeichnungen <code>«metaclass»</code> sowie den Rollen- bzw. Generalisierungskontexten <code>Namespace</code> und <code>PackagableElement</code>.\n</li><li><code>«extends»</code>-Beziehung: Gerichtete Stereotyp-Erweiterung von <code>atpPackage</code> nach <code>Kernel::Package</code>, annotiert mit der Eigenschaft <code>{required}</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es ist kein dynamischer Laufzeit- oder Sequenzablauf modelliert. Die Semantik definiert die zwingende (<code>{required}</code>) Erweiterung und Typisierung regulärer UML-Packages zu AUTOSAR-Packages auf Definitionsebene.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für AUTOSAR-Metamodellierungswerkzeuge und Profildefinitionen:</p>\n<ul class=\"fig-list\"><li>Jedes als AUTOSAR-Paket fungierende Modellelement basiert auf der Metaklasse <code>Kernel::Package</code>.\n</li><li>Durch die Profilbeschränkung <code>{required}</code> muss das Stereotyp <code>atpPackage</code> zwingend auf die Metaklasse angewendet werden, um standardkonforme AUTOSAR-Paketstrukturen im Metamodell abzubilden.\n</li><li>Werkzeug- und Codegeneratoren müssen Paketelemente (<code>PackagableElement</code>) innerhalb dieses Namensraums (<code>Namespace</code>) gemäß den Vorgaben des Template Modeling Guide verarbeiten.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-cd3c8d26ceb45a60", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Profildiagramm (Metamodell-Ausschnitt) im Kontext des AUTOSAR Template Modeling Guide (M2-Ebene). Das Diagramm spezifiziert die Definition des Stereotyps <code>«atpPackage»</code> sowie dessen Bindung an die UML-Infrastruktur-Metaklasse <code>Kernel::Package</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst zwei Modellelemente und eine Extension-Beziehung:</p>\n<ul class=\"fig-list\"><li><code>atpPackage</code>: Stereotyp-Definition zur Kennzeichnung von AUTOSAR-Paketen.\n</li><li><code>Kernel::Package</code>: Ziel-Metaklasse mit den stereotypischen Kennzeichnungen <code>«metaclass»</code> sowie den Rollen- bzw. Generalisierungskontexten <code>Namespace</code> und <code>PackagableElement</code>.\n</li><li><code>«extends»</code>-Beziehung: Gerichtete Stereotyp-Erweiterung von <code>atpPackage</code> nach <code>Kernel::Package</code>, annotiert mit der Eigenschaft <code>{required}</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es ist kein dynamischer Laufzeit- oder Sequenzablauf modelliert. Die Semantik definiert die zwingende (<code>{required}</code>) Erweiterung und Typisierung regulärer UML-Packages zu AUTOSAR-Packages auf Definitionsebene.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für AUTOSAR-Metamodellierungswerkzeuge und Profildefinitionen:</p>\n<ul class=\"fig-list\"><li>Jedes als AUTOSAR-Paket fungierende Modellelement basiert auf der Metaklasse <code>Kernel::Package</code>.\n</li><li>Durch die Profilbeschränkung <code>{required}</code> muss das Stereotyp <code>atpPackage</code> zwingend auf die Metaklasse angewendet werden, um standardkonforme AUTOSAR-Paketstrukturen im Metamodell abzubilden.\n</li><li>Werkzeug- und Codegeneratoren müssen Paketelemente (<code>PackagableElement</code>) innerhalb dieses Namensraums (<code>Namespace</code>) gemäß den Vorgaben des Template Modeling Guide verarbeiten.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-1111e2a853407805", "to": "FIG-0544b693ef310242", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0544b693ef310242", "to": "FIG-cd3c8d26ceb45a60", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
